import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String customFilter = req.getParameter("filter");
        String outputFormat = req.getParameter("fmt");

        // Template-based query construction for different report types
        Map<String, String> templates = new HashMap<>();
        templates.put("sales", "SELECT id, product, amount, ts FROM sales WHERE ts BETWEEN '${start}' AND '${end}'");
        templates.put("inventory", "SELECT sku, warehouse, qty FROM inventory WHERE updated > '${start}'");
        templates.put("custom", "SELECT * FROM ${table} WHERE ${condition}");

        String queryTemplate = templates.getOrDefault(reportType, templates.get("sales"));

        // Parse date range
        String[] dates = parseDateRange(dateRange);

        // Build substitution map
        Map<String, String> valuesMap = new HashMap<>();
        valuesMap.put("start", dates[0]);
        valuesMap.put("end", dates[1]);

        if ("custom".equals(reportType) && customFilter != null) {
            // Custom reports allow flexible filtering
            String[] parts = customFilter.split(":", 2);
            valuesMap.put("table", sanitizeIdentifier(parts[0]));
            valuesMap.put("condition", parts.length > 1 ? parts[1] : "1=1");
        }

        StringSubstitutor sub = new StringSubstitutor(valuesMap);
        String finalQuery = sub.replace(queryTemplate);

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(finalQuery)) {

            out.print(resultSetToJson(rs, outputFormat));
        } catch (SQLException e) {
            resp.setStatus(500);
            out.print("{\"error\": \"Query execution failed\"}");
        }
    }

    private String sanitizeIdentifier(String input) {
        // Only allow alphanumeric and underscore for table names
        return input.replaceAll("[^a-zA-Z0-9_]", "");
    }

    private String[] parseDateRange(String range) {
        if (range == null || !range.contains(",")) {
            return new String[]{"2024-01-01", "2024-12-31"};
        }
        return range.split(",", 2);
    }

    private String resultSetToJson(ResultSet rs, String fmt) throws SQLException {
        StringBuilder sb = new StringBuilder("[");
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        boolean first = true;
        int rowLimit = "summary".equals(fmt) ? 10 : 1000;
        int count = 0;

        while (rs.next() && count < rowLimit) {
            if (!first) sb.append(",");
            sb.append("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) sb.append(",");
                sb.append("\"").append(meta.getColumnName(i)).append("\":");
                sb.append("\"").append(rs.getString(i)).append("\"");
            }
            sb.append("}");
            first = false;
            count++;
        }
        sb.append("]");
        return sb.toString();
    }
}
